#ifndef REGISTER_FILE_H
#define REGISTER_FILE_H

#include <vector>
#include <string>
#include <cstring>

// Assuming Immediate is defined elsewhere or will be provided.
typedef int Immediate;

class RegisterFile {
    static const int REG_NUM = 32;
public:
    Immediate prev[REG_NUM];
    Immediate next[REG_NUM];

    RegisterFile();
    void tick();
    Immediate read(int id);
    void write(int id, Immediate val);
    void debug();
};

#endif // REGISTER_FILE_H
